@@ -42,9 +42,9 @@
 const levels=[6,8,10];let levelIndex=0,cards=[],first=null,lock=false,moves=0,matched=0,seconds=60,ticker=null,playing=false,soundOn=false,ctx=null;
 const grid=document.querySelector('#grid'),timerEl=document.querySelector('#timer'),movesEl=document.querySelector('#moves'),progress=document.querySelector('#progress'),message=document.querySelector('#message'),overlay=document.querySelector('#overlay'),nextBtn=document.querySelector('#next');
 function playTone(freq=520,duration=.11){if(!soundOn)return;try{ctx??=new(window.AudioContext||window.webkitAudioContext)();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(.055,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+duration)}catch{}}
 function setMessage(text){message.innerHTML=text}
-function start(){clearInterval(ticker);first=null;lock=false;moves=0;matched=0;seconds=60;playing=true;timerEl.textContent='01:00';movesEl.textContent='00';progress.style.width='0%';document.querySelector('#level').textContent=`Night ${String(levelIndex+1).padStart(2,'0')}`;setMessage('Take a breath. <strong>Let the sparks find you.</strong>');grid.innerHTML='';grid.style.gridTemplateColumns=levels[levelIndex]===6?'repeat(4,1fr)':'repeat(4,1fr)';const chosen=deck.slice(0,levels[levelIndex]);cards=[...chosen,...chosen].map((item,i)=>({...item,id:i,face:Math.random()})).sort(()=>Math.random()-.5);cards.forEach(card=>{const el=document.createElement('button');el.className='card';el.type='button';el.setAttribute('aria-label','Mystery card');el.dataset.id=card.id;el.innerHTML=`<span class="card-inner"><span class="face back"></span><span class="face front"><span class="icon">${card.icon}</span><span class="name">${card.name}</span></span></span>`;el.addEventListener('click',()=>flip(el,card));grid.append(el)});ticker=setInterval(()=>{if(!playing)return;seconds--;timerEl.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(seconds<=10)timerEl.style.color='#ff8baa';else timerEl.style.color='';if(seconds<=0)finish(false)},1000)}
+function start(){clearInterval(ticker);first=null;lock=false;moves=0;matched=0;seconds=60;playing=true;timerEl.style.color='';timerEl.textContent='01:00';movesEl.textContent='00';progress.style.width='0%';document.querySelector('#level').textContent=`Night ${String(levelIndex+1).padStart(2,'0')}`;setMessage('Take a breath. <strong>Let the sparks find you.</strong>');grid.innerHTML='';grid.style.gridTemplateColumns=levels[levelIndex]===6?'repeat(4,1fr)':'repeat(4,1fr)';const chosen=deck.slice(0,levels[levelIndex]);cards=[...chosen,...chosen].map((item,i)=>({...item,id:i,face:Math.random()})).sort(()=>Math.random()-.5);cards.forEach(card=>{const el=document.createElement('button');el.className='card';el.type='button';el.setAttribute('aria-label','Mystery card');el.dataset.id=card.id;el.innerHTML=`<span class="card-inner"><span class="face back"></span><span class="face front"><span class="icon">${card.icon}</span><span class="name">${card.name}</span></span></span>`;el.addEventListener('click',()=>flip(el,card));grid.append(el)});ticker=setInterval(()=>{if(!playing)return;seconds--;timerEl.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(seconds<=10)timerEl.style.color='#ff8baa';else timerEl.style.color='';if(seconds<=0)finish(false)},1000)}
 function flip(el,card){if(!playing||lock||el.classList.contains('flipped')||el.classList.contains('matched'))return;if(!ticker)return;el.classList.add('flipped');el.setAttribute('aria-label',card.name);playTone(420);if(!first){first={el,card};return}moves++;movesEl.textContent=String(moves).padStart(2,'0');if(first.card.name===card.name){first.el.classList.add('matched');el.classList.add('matched');first.el.setAttribute('aria-label',`${card.name}, matched`);el.setAttribute('aria-label',`${card.name}, matched`);first=null;matched++;progress.style.width=`${matched/levels[levelIndex]*100}%`;setMessage('<strong>There it is.</strong> A little spark. ✦');playTone(720,.18);if(matched===levels[levelIndex]){playing=false;clearInterval(ticker);ticker=null;setTimeout(()=>finish(true),550)}}else{lock=true;const prev=first;first=null;setMessage('Not quite. <strong>Trust your instincts.</strong>');setTimeout(()=>{prev.el.classList.remove('flipped');el.classList.remove('flipped');prev.el.setAttribute('aria-label','Mystery card');el.setAttribute('aria-label','Mystery card');lock=false},850)}}
 function finish(won){playing=false;clearInterval(ticker);ticker=null;document.querySelector('#modal-icon').textContent=won?'✦':'♡';document.querySelector('#modal-title').textContent=won?'A perfect match.':'The night is young.';document.querySelector('#modal-copy').textContent=won?`You found every spark in ${moves} moves, with ${timerEl.textContent} to spare. Chemistry looks good on you.`:'Time slipped away, but the best connections are worth another look. Ready to try again?';document.querySelector('#result').textContent=won?`Night ${String(levelIndex+1).padStart(2,'0')} · ${moves} moves`:'No pressure. Take another chance.';nextBtn.classList.toggle('hidden',!won||levelIndex===levels.length-1);document.querySelector('#again').textContent=won&&levelIndex===levels.length-1?'Play again':'Restart night';overlay.classList.add('show');playTone(won?760:280,.25)}
 document.querySelector('#restart').addEventListener('click',()=>{levelIndex=0;start()});document.querySelector('#again').addEventListener('click',()=>{overlay.classList.remove('show');if(levelIndex===levels.length-1&&matched===levels[levelIndex])levelIndex=0;start()});nextBtn.addEventListener('click',()=>{overlay.classList.remove('show');levelIndex=Math.min(levelIndex+1,levels.length-1);start()});document.querySelector('#sound').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫  Sound on':'♫  Sound off';e.currentTarget.setAttribute('aria-pressed',String(soundOn));playTone(600)});overlay.addEventListener('click',e=>{if(e.target===overlay){overlay.classList.remove('show')}});document.addEventListener('keydown',e=>{if(e.key==='Escape')overlay.classList.remove('show')});start();
 })();
